 check(argc==2,"Fixture path");auto root=std::filesystem::u8path(argv[1]);check(root.filename()=="sync-policy-fixture","Named fixture");std::filesystem::remove_all(root);std::filesystem::create_directories(root/"mods.d");{StudyWorker worker(root.u8string());check(!worker.can_transmit_sync(false).get(),"Sync disabled at startup");worker.configure_sync(s).get();check(worker.can_transmit_sync(false).get()&&!worker.can_transmit_sync(true).get(),"FIFO config and echo guard");auto decision=worker.plan_incoming_sync(n).get();check(decision.route==SyncRoute::reference_list&&decision.navigation.module=="Original","Unknown module retained for reference-list review");worker.configure_sync({}).get();check(worker.plan_incoming_sync(n).get().route==SyncRoute::ignore,"Disable takes effect before queued input");}std::filesystem::remove_all(root);std::cout<<"Sync policy checks passed (no wire transport)\n";return 0;
